import React, {  } from "react";

import { getStore, updStore } from "../../../stores/Utils";

import "./dashboard.css"
import {  UpdUser_Cmpt } from "..";
import { OpenModal } from "../../../components/DialogHRM";

const UpdUser = UpdUser_Cmpt();



const UserItem  = ({ data }) => {
	

	
	const refreshAccs =  () => {
		window.location.reload();
	}

	const update = async () => {
		updStore("upd_user", data);
		updStore("upd_user_bck", JSON.parse(JSON.stringify(data)));
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] = <UpdUser confirm={refreshAccs} />
		
		OpenModal(modaldata);
	}

	


	
	//let subAcc = getStore("sub_user_group")?.[data.userId];
	
	return (
		<div className="item_acc">
			<div className="_dsplFlx user_item_box user_header"  onClick={update}>
				<div className="name tr_bar_35">
					{data?.name}
				</div>
				<div style={{marginLeft: 12}}></div>
				<div className="code tr_bar_55" >
					{data?.email} 
				</div>
			</div>
		</div>
	)
}
export default UserItem;